//! Samples for core's template-instance reconciler, generated by the management handlers.
mod common;

use std::collections::BTreeMap;
use std::fmt::Write;
use std::fs;
use std::path::PathBuf;

use basal_host::{EventBody, EventDecl, EventOrigin, OpDecl, OpKind};
use basal_module::caller::{self, Caller};
use common::{Fixture, HOUR, Options, fixture};
use serde_json::{Value, json};
use sha2::{Digest, Sha256};
use subc_protocol::Principal;

const MANIFEST: &str = include_str!("../../../templates/docs-proposals/manifest.json");
const SCRIPT: &str = include_str!("../../../templates/docs-proposals/flow.js");
const OWNER: &str = "agent_0000000000000001";
const MOVING: &str = "agent_0000000000000002";
const UNKNOWN: &str = "agent_0000000000000003";
const INSTANTIATE: &str = "flow.instantiate";

fn setup(core: &Caller) -> Fixture {
    let f = fixture("core-instantiate-vectors", Options::default());
    f.catalog.add_named_agent(OWNER, "Sample owner");
    f.catalog.add_named_agent(MOVING, "Sample moving agent");
    f.catalog.set_flow_capable("magic-context", true);
    for op in ["events_get", "docs_proposals.state"] {
        f.catalog.set_op(
            "magic-context",
            op,
            OpDecl {
                kind: Some(OpKind::Query),
                cause_echo: false,
                shell_capable: false,
            },
        );
    }
    f.catalog.set_event(
        "magic-context",
        "docs_proposal",
        1,
        EventDecl {
            headers: vec!["event_key".into(), "project_id".into()],
            origin: EventOrigin::External,
            body: EventBody::Resolved {
                resolve_op: "events_get".into(),
            },
        },
    );
    // Approval lives in core; basal registers the exact version core has selected.
    // The samples instantiate version 1, so register a first version built from
    // the shipped manifest (which describes a later upgrade).
    let mut first: Value = serde_json::from_str(MANIFEST).unwrap();
    first["version"] = json!(1);
    first.as_object_mut().unwrap().remove("changes");
    let registered = f
        .module
        .handle(
            core,
            "package.register",
            json!({"manifest":first.to_string(),"script":SCRIPT}),
        )
        .unwrap();
    assert_eq!(registered["package"], "docs-proposals");
    assert_eq!(registered["version"], 1);
    f
}

fn instantiate(agent: &str, params: Value, expires_in: &str) -> Value {
    json!({"template":"docs-proposals","version":1,"agent_id":agent,"params":params,"expires_in":expires_in})
}

fn record(
    f: &Fixture,
    core: &Caller,
    name: &str,
    method: &str,
    params: Value,
    expected_error: Option<&str>,
) -> Value {
    let request = json!({"method":method,"params":params});
    match f.module.handle(core, method, params) {
        Ok(reply) => {
            assert!(expected_error.is_none(), "{name}: unexpectedly succeeded");
            json!({"name":name,"request":request,"reply":reply})
        }
        Err(error) => {
            assert_eq!(Some(error.code.as_str()), expected_error, "{name}: {error}");
            let mut body = json!({"code":error.code,"message":error.message});
            if let Some(detail) = error.detail {
                body["detail"] = detail;
            }
            json!({"name":name,"request":request,"error":body})
        }
    }
}

fn vectors() -> [Value; 8] {
    let core = caller::from_route(
        Some(&Principal::Reserved {
            module_id: "prefrontal".into(),
        }),
        None,
    );
    assert_eq!(core, Caller::Core);
    let f = setup(&core);
    let record = |name, method, params, expected_error| {
        record(&f, &core, name, method, params, expected_error)
    };
    let request = instantiate(OWNER, json!({"project_id":"pj-sample"}), "30d");
    let success = record("success", INSTANTIATE, request.clone(), None);
    f.clock.advance(24 * HOUR);
    let repeat = record("repeat_extends", INSTANTIATE, request.clone(), None);
    let param_missing = record(
        "param_missing",
        INSTANTIATE,
        instantiate(OWNER, json!({}), "30d"),
        Some("param_missing"),
    );
    let mut too_long = request.clone();
    too_long["expires_in"] = json!("366d");
    let lifetime_too_long = record(
        "lifetime_too_long",
        INSTANTIATE,
        too_long,
        Some("lifetime_too_long"),
    );

    // The successful instance already occupies one of the 100 per-agent slots.
    for n in 1..100 {
        f.module
            .handle(
                &core,
                INSTANTIATE,
                instantiate(
                    OWNER,
                    json!({"project_id":format!("pj-seed-{n:03}")}),
                    "30d",
                ),
            )
            .unwrap();
    }
    let instance_limit_reached = record(
        "instance_limit_reached",
        INSTANTIATE,
        instantiate(OWNER, json!({"project_id":"pj-over-limit"}), "30d"),
        Some("instance_limit_reached"),
    );
    let mut unknown = request.clone();
    unknown["agent_id"] = json!(UNKNOWN);
    let agent_unknown = record("agent_unknown", INSTANTIATE, unknown, Some("agent_unknown"));

    f.module
        .rt
        .store()
        .write(|tx| {
            basal_core::agent_move::freeze(
                tx,
                MOVING,
                "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
                f.clock.now_ms(),
            )?
            .map_err(|busy| basal_core::CoreError::Invalid(busy.reason))
        })
        .unwrap();
    let mut moving = request;
    moving["agent_id"] = json!(MOVING);
    let agent_moving = record("agent_moving", INSTANTIATE, moving, Some("agent_moving"));
    let end = record(
        "end_success",
        "flow.instance.end",
        json!({"flow_id":success["reply"]["flow_id"]}),
        None,
    );

    [
        success,
        repeat,
        param_missing,
        lifetime_too_long,
        instance_limit_reached,
        agent_unknown,
        agent_moving,
        end,
    ]
}

#[test]
fn flow_instantiate_core_vectors_are_generated_and_pinned() {
    let dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../test-vectors/flow-instantiate-core-v1");
    let write = std::env::var_os("BASAL_WRITE_VECTORS").is_some_and(|value| value == "1");
    let pin = |name: &str, text: &str| {
        let path = dir.join(name);
        if write {
            fs::write(&path, text).unwrap();
        }
        assert_eq!(
            fs::read_to_string(&path).unwrap(),
            text,
            "{name} drifted; regenerate with BASAL_WRITE_VECTORS=1"
        );
    };
    let mut files = BTreeMap::new();
    files.insert(
        "README.md".to_owned(),
        fs::read(dir.join("README.md")).unwrap(),
    );
    for vector in vectors() {
        let name = format!("{}.json", vector["name"].as_str().unwrap());
        let bytes = format!("{}\n", serde_json::to_string_pretty(&vector).unwrap());
        pin(&name, &bytes);
        files.insert(name, bytes.into_bytes());
    }
    let mut sums = String::new();
    for (name, bytes) in files {
        writeln!(sums, "{:x}  {name}", Sha256::digest(&bytes)).unwrap();
    }
    pin("SHA256SUMS", &sums);
}
